'use strict';
class MineEffects{
 constructor(game,board,reduced){this.game=game;this.board=board;this.reduced=reduced;this.animations=new Set();this.nodes=new Set();}
 get enabled(){return !this.reduced?.matches&&!document.hidden&&!this.game.classList.contains('motion-paused');}
 play(node,frames,options={}){if(!this.enabled||!node?.animate)return null;const a=node.animate(frames,{duration:350,easing:'cubic-bezier(.2,.7,.2,1)',...options});this.animations.add(a);a.finished.then(()=>this.animations.delete(a),()=>this.animations.delete(a));return a;}
 clear(){for(const a of this.animations)a.cancel();this.animations.clear();for(const n of this.nodes)n.remove();this.nodes.clear();}
 point(node,layer){const a=node.getBoundingClientRect(),b=layer.getBoundingClientRect();return {x:a.left+a.width/2-b.left,y:a.top+a.height/2-b.top,w:a.width,h:a.height};}
 effect(layer,cls,x,y,text=''){const n=document.createElement('span');n.className=cls;n.textContent=text;n.style.left=x+'px';n.style.top=y+'px';layer.append(n);this.nodes.add(n);return n;}
 fade(node,frames,options){const a=this.play(node,frames,options);const clean=()=>{this.nodes.delete(node);node.remove()};if(a)a.finished.then(clean,clean);else clean();}
 ring(node,cls='mine-wave',scale=6,duration=520){if(!this.enabled)return;const layer=document.getElementById('board-effects'),p=this.point(node,layer),n=this.effect(layer,cls,p.x,p.y);this.fade(n,[{transform:'translate(-50%,-50%) scale(.3)',opacity:.7},{transform:`translate(-50%,-50%) scale(${scale})`,opacity:0}],{duration,easing:'cubic-bezier(.12,.65,.3,1)'});}
 shards(node,blast=false){if(!this.enabled)return;const layer=document.getElementById('board-effects'),p=this.point(node,layer),count=blast?24:6;for(let i=0;i<count;i++){const a=i*2.399,spread=blast?45+(i%5)*20:15+(i%3)*10,n=this.effect(layer,'mine-shard',p.x,p.y);n.style.background=blast?(i%3===0?'#ffd3a0':i%2?'#eaa8b8':'#bba4f2'):(i%2?'#adebf2':'#b0a0ec');this.fade(n,[{transform:`translate(-50%,-50%) rotate(${i*33}deg) scale(1)`,opacity:.95},{transform:`translate(${Math.cos(a)*spread}px,${Math.sin(a)*spread+(blast?35:8)}px) rotate(${i*33+120}deg) scale(.15)`,opacity:0}],{duration:blast?650:420,easing:'cubic-bezier(.15,.6,.4,1)'});}}
 reveal(indices,origin,amount=indices.length*10){if(!this.enabled)return;const center=this.board.children[origin];this.ring(center,'mine-wave',indices.length>4?12:4,indices.length>4?650:420);this.shards(center);for(const index of indices){const distance=Math.abs(index%6-origin%6)+Math.abs(Math.floor(index/6)-Math.floor(origin/6)),node=this.board.children[index];this.play(node,[{transform:'scale(.91)',filter:'brightness(1.7)',boxShadow:'inset 0 0 0 1px #b9eeff88'},{transform:'scale(1.035)',filter:'brightness(1.2)',offset:.6,boxShadow:'inset 0 0 0 1px #83dcff44'},{transform:'scale(1)',filter:'brightness(1)',boxShadow:'inset 0 0 0 1px #83dcff00'}],{duration:330,delay:Math.min(280,distance*32)});}this.collect(center,amount);}
 collect(node,amount){if(!this.enabled)return;const layer=document.getElementById('scene-effects'),p=this.point(node,layer),end=this.point(document.getElementById('coins'),layer),dx=end.x-p.x,dy=end.y-p.y;const label=this.effect(layer,'score-flight',p.x,p.y,'+'+amount);this.fade(label,[{transform:'translate(-50%,-50%) scale(.7)',opacity:0},{transform:'translate(-50%,-80%) scale(1)',opacity:1,offset:.18},{transform:'translate(-50%,-100%) scale(1)',opacity:1,offset:.45},{transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) scale(.55)`,opacity:0}],{duration:840});for(let i=0;i<5;i++){const bit=this.effect(layer,'score-light',p.x+(i-2)*4,p.y);this.fade(bit,[{transform:'translate(0,0)',opacity:0},{transform:`translate(${(i-2)*8}px,-12px)`,opacity:.8,offset:.15},{transform:`translate(${dx}px,${dy}px)`,opacity:0}],{duration:650,delay:160+i*24});}}
 flag(node){this.ring(node,'flag-ring',3,360);this.play(node.querySelector('.flagMark'),[{transform:'translateY(-10px) scale(.55)',opacity:0},{transform:'translateY(1px) scale(1.08)',opacity:1,offset:.7},{transform:'translateY(-1px) scale(1)',opacity:1}],{duration:270});}
 explode(node){if(!this.enabled)return;const layer=document.getElementById('board-effects'),p=this.point(node,layer),core=this.effect(layer,'blast-core',p.x,p.y);this.fade(core,[{transform:'translate(-50%,-50%) scale(.1)',opacity:1},{transform:'translate(-50%,-50%) scale(1.2)',opacity:1,offset:.15},{transform:'translate(-50%,-50%) scale(2.8)',opacity:0}],{duration:460});this.ring(node,'blast-ring',11,650);this.ring(node,'mine-wave',7,490);this.shards(node,true);this.play(this.board,[{transform:'translateX(0)'},{transform:'translateX(-3px)',offset:.2},{transform:'translateX(3px)',offset:.4},{transform:'translateX(-2px)',offset:.65},{transform:'translateX(0)'}],{duration:230});this.play(document.getElementById('coins'),[{transform:'scale(1.2)',color:'#ffd3c1'},{transform:'scale(1)',color:'#f2a6ac'}],{duration:450});}
 win(){if(!this.enabled)return;for(let i=0;i<this.board.children.length;i++){const cell=this.board.children[i];if(!cell.classList.contains('is-open'))continue;this.play(cell,[{boxShadow:'inset 0 0 0 1px #fce6a000',filter:'brightness(1)'},{boxShadow:'inset 0 0 0 1px #fce6a0bb',filter:'brightness(1.35)',offset:.35},{boxShadow:'inset 0 0 0 1px #fce6a000',filter:'brightness(1)'}],{duration:420,delay:Math.floor(i/6)*42});}this.ring(this.board.children[26],'mine-wave',17,760);}
 dialog(won){this.play(document.getElementById('dialog'),[{transform:'translateY(12px) scale(.96)',opacity:.4},{transform:'translateY(0) scale(1)',opacity:1}],{duration:won?340:250});}
}
